/**
 * RFC 9457 Problem Details extended with stable ohmyhost recovery fields.
 */
export type ProblemDetails = {
  type: string;
  title: string;
  status: number;
  detail?: string;
  instance?: string;
  code:
    | "invalid_request"
    | "unauthenticated"
    | "forbidden"
    | "organization_required"
    | "resource_not_found"
    | "idempotency_key_reused"
    | "project_handle_unavailable"
    | "project_identity_unavailable"
    | "deployment_plan_expired"
    | "deployment_plan_incompatible"
    | "confirmation_expired"
    | "confirmation_invalid"
    | "etag_mismatch"
    | "promotion_source_stale"
    | "promotion_target_stale"
    | "promotion_invalid_target"
    | "mail_domain_conflict"
    | "mail_domain_required"
    | "mail_capacity_unavailable"
    | "storage_jurisdiction_conflict"
    | "shared_data_requires_promotion"
    | "production_deployment_required"
    | "framework_conversion_required"
    | "repository_configuration_missing"
    | "migration_filename_noncanonical"
    | "environment_secret_mutation_blocked"
    | "workers_runtime_incompatible"
    | "project_handle_invalid"
    | "project_handle_taken"
    | "project_handle_unchanged"
    | "project_rename_blocked"
    | "payload_too_large"
    | "rate_limited"
    | "insufficient_organization_credits"
    | "paid_plan_required"
    | "project_budget_exceeded"
    | "compute_performance_paid_required"
    | "compute_performance_unavailable"
    | "database_write_pending"
    | "database_access_limit"
    | "compute_change_pending"
    | "compute_change_conflict"
    | "billing_purchase_conflict"
    | "billing_recharge_conflict"
    | "github_connection_required"
    | "github_connection_revoked"
    | "repository_not_installed"
    | "cloudflare_zone_not_bound"
    | "cloudflare_authorization_closed"
    | "project_notes_conflict"
    | "project_export_not_ready"
    | "powered_by_flag_required"
    | "interactive_login_required"
    | "api_key_creation_uncertain"
    | "api_key_permissions_unavailable"
    | "reconciliation_exhausted"
    | "service_unavailable";
  request_id: string;
  retryable: boolean;
  /**
   * Optional machine-readable retry delay for a rate limit, matching Retry-After.
   */
  retry_after_seconds?: number;
  suggested_action: string;
};

/**
 * Durable record returned for an accepted asynchronous mutation. Optional reconciliation is a current observation for queued/running work, separate from immutable terminal state. A completed reconciliation attempt alone does not mean the operation succeeded.
 */
export type Operation = {
  /**
   * The active operation holding this queued operation's project mutation claim.
   */
  blocking_operation_id?: Ulid;
  /**
   * The deployment this operation created (deploy, promotion or rollback), in every state. After a failure, read its diagnostics with deployment logs.
   */
  deployment_id?: Ulid;
  id: Ulid;
  state: "queued" | "running" | "succeeded" | "failed" | "cancelled";
  created_at: string;
  updated_at: string;
  result?: {
    [key: string]: unknown;
  };
  error?: OperationFailure;
  progress?: OperationDeploymentProgress;
  reconciliation?: OperationReconciliation;
};

/**
 * Current deployment dependency observation, separate from immutable operation history. Poll the same operation; mail readiness does not mean application activation.
 */
export type OperationDeploymentProgress = {
  /**
   * Actual successful build completion time when this operation ran a build; omitted for reused artifacts without a current build.
   */
  build_completed_at?: string;
  phase: "queued" | "building" | "publishing" | "waiting_for_mail" | "mail_status_unavailable";
  project_id: Ulid;
  deployment_id: Ulid;
  observed_at: string;
  next_poll_after_seconds: 60;
  suggested_action: string;
};

export type OperationReconciliation = {
  state: "required" | "pending";
  /**
   * Active attempt for pending reconciliation; null when a new confirmed reconciliation is required.
   */
  attempt_id: Ulid | null;
  observed_at: string;
  suggested_action: string;
};

/**
 * Provider-neutral status of one idempotent reconciliation attempt.
 */
export type ProviderReconciliationAttempt = {
  reconciliation_id: Ulid;
  operation_id: Ulid;
  state: "completed" | "pending" | "uncertain";
};

